import { expect, test } from '../fixtures';

/** A secret the flow was driven with. Set it in the environment or in sova/.env. */
function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) throw new Error(`${name} is not set. Add it to sova/.env or the environment.`);
  return value;
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Sign in user', async ({ page }) => {
  await test.step('Open the login page', async () => {
    await page.goto('/login');
  });

  await test.step('Type the user name', async () => {
    await page.getByRole('textbox', { name: 'User Name or Email', exact: true }).fill(env('USER_NAME'));
  });

  await test.step('Type the password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill(env('USER_PASSWORD'));
  });

  await test.step('Press Submit', async () => {
    await page.getByRole('button', { name: 'Submit', exact: true }).click();
  });

  await test.step('The logout link is shown', async () => {
    await expect(page.locator('a[href="/logout"]')).toBeVisible();
  });

  await test.step('Keep the signed-in session for the other tests', async () => {
    await page.context().storageState({ path: process.env.SOVA_AUTH_STATE_USER!, indexedDB: true });
  });
});
